package com.minimall.trade.shipping.mock;
import com.minimall.trade.shipping.gateway.*;import com.minimall.common.persistence.Database;import com.minimall.common.util.*;import com.minimall.common.api.BusinessException;import org.springframework.stereotype.Service;import org.springframework.context.annotation.Profile;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @Profile("(local | test) & !prod") @ConditionalOnProperty(name="mall.simulation.enabled",havingValue="true") public class MockShippingGateway implements ShippingGateway {
 private final Database db;private final Json json;private final Clock clock;public MockShippingGateway(Database db,Json json,Clock clock){this.db=db;this.json=json;this.clock=clock;}
 @Transactional public ShipmentResult create(ShipmentRequest r){String payload=json.write(r);db.update("INSERT INTO mock_shipment(shipment_no,request_json,fail_query) VALUES(?,?,0) ON DUPLICATE KEY UPDATE shipment_no=shipment_no",r.shipmentNo(),payload);var row=db.required("SELECT * FROM mock_shipment WHERE shipment_no=? FOR UPDATE",r.shipmentNo());Checks.state(row.text("request_json").equals(payload),"相同运单号的内容不一致");if(db.count("SELECT COUNT(*) AS value FROM mock_shipment_track WHERE shipment_no=?",r.shipmentNo())==0)append(r.shipmentNo(),new ShipmentTrack("created:"+r.shipmentNo(),clock.instant(),"CREATED","物流已受理"));return new ShipmentResult(r.shipmentNo(),true);}
 public List<ShipmentTrack> query(String no){var row=db.required("SELECT * FROM mock_shipment WHERE shipment_no=?",no);if(row.flag("fail_query"))throw BusinessException.unavailable();return db.rows("SELECT * FROM mock_shipment_track WHERE shipment_no=? ORDER BY event_time,id LIMIT 500",no).stream().map(r->new ShipmentTrack(r.text("event_id"),r.instant("event_time"),r.text("status"),r.text("description"))).toList();}
 @Transactional public void append(String no,ShipmentTrack t){db.required("SELECT * FROM mock_shipment WHERE shipment_no=? FOR UPDATE",no);Checks.text(t.eventId(),1,100,"轨迹事件号");Checks.text(t.description(),1,255,"轨迹描述");if(t.eventTime()==null||!Set.of("CREATED","IN_TRANSIT","DELIVERED").contains(t.status()))throw BusinessException.bad("轨迹不合法");db.update("INSERT INTO mock_shipment_track(shipment_no,event_id,event_time,status,description) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",no,t.eventId(),t.eventTime(),t.status(),t.description());}
 @Transactional public void failQueries(String no,boolean fail){db.required("SELECT shipment_no FROM mock_shipment WHERE shipment_no=? FOR UPDATE",no);db.update("UPDATE mock_shipment SET fail_query=? WHERE shipment_no=?",fail,no);}
}
